import { useState } from 'react';
import { Alert, Button, Card, Container, Form } from 'react-bootstrap';
import { Navigate, useNavigate } from 'react-router-dom';
import api from '../api';
import { getUser, setUser } from '../auth';

const styles = {
  page: {
    minHeight: '100vh',
    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 50%, #f093fb 100%)',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    padding: '24px',
  },
  card: {
    width: 420,
    border: 'none',
    borderRadius: 20,
    boxShadow: '0 20px 50px rgba(0, 0, 0, 0.25)',
    background: 'rgba(255, 255, 255, 0.95)',
    backdropFilter: 'blur(10px)',
  },
  title: {
    fontWeight: 800,
    fontSize: '2rem',
    background: 'linear-gradient(90deg, #667eea, #764ba2)',
    WebkitBackgroundClip: 'text',
    WebkitTextFillColor: 'transparent',
  },
  subtitle: {
    color: '#6c757d',
    fontSize: '0.95rem',
  },
  input: {
    borderRadius: 12,
    padding: '12px 16px',
    border: '2px solid #e6e8f5',
    background: '#f8f9ff',
  },
  button: {
    border: 'none',
    borderRadius: 12,
    padding: '12px',
    fontWeight: 600,
    letterSpacing: '0.5px',
    background: 'linear-gradient(90deg, #667eea, #764ba2)',
    boxShadow: '0 8px 20px rgba(118, 75, 162, 0.4)',
    transition: 'transform 0.15s ease, box-shadow 0.15s ease',
  },
};

function Login() {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [hover, setHover] = useState(false);

  if (getUser()) {
    return <Navigate to="/subjects" replace />;
  }

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    if (!email.trim() || !password.trim()) {
      setError('Vui lòng nhập đầy đủ email và mật khẩu.');
      return;
    }

    try {
      setLoading(true);
      const res = await api.get('/accounts', {
        params: { email: email.trim(), password },
      });
      const account = res.data[0];

      if (!account) {
        setError('Email hoặc mật khẩu không đúng.');
        return;
      }
      if (String(account.status).toLowerCase() !== 'active') {
        setError('Tài khoản của bạn đang bị khóa (Inactive).');
        return;
      }

      setUser({ id: account.id, email: account.email, role: account.role });
      navigate('/subjects');
    } catch {
      setError('Không thể kết nối đến server. Hãy chạy: npm run server');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.page}>
      <Container className="d-flex justify-content-center">
        <Card style={styles.card}>
          <Card.Body className="p-4 p-md-5">
            <div className="text-center mb-4">
              <Card.Title style={styles.title}>Sign In</Card.Title>
              <div style={styles.subtitle}>Chào mừng bạn quay trở lại 👋</div>
            </div>

            {error && (
              <Alert variant="danger" style={{ borderRadius: 12 }}>
                {error}
              </Alert>
            )}

            <Form onSubmit={handleSubmit} noValidate>
              <Form.Group className="mb-3" controlId="email">
                <Form.Control
                  type="email"
                  placeholder="Email"
                  style={styles.input}
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                />
              </Form.Group>
              <Form.Group className="mb-4" controlId="password">
                <Form.Control
                  type="password"
                  placeholder="Password"
                  style={styles.input}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
              </Form.Group>
              <div className="d-grid">
                <Button
                  type="submit"
                  disabled={loading}
                  style={{
                    ...styles.button,
                    transform: hover && !loading ? 'translateY(-2px)' : 'none',
                    boxShadow: hover && !loading
                      ? '0 12px 28px rgba(118, 75, 162, 0.55)'
                      : styles.button.boxShadow,
                  }}
                  onMouseEnter={() => setHover(true)}
                  onMouseLeave={() => setHover(false)}
                >
                  {loading ? 'Đang đăng nhập...' : 'Login'}
                </Button>
              </div>
            </Form>
          </Card.Body>
        </Card>
      </Container>
    </div>
  );
}

export default Login;
